/**
 * @method
 * @name grd_inqDiscls_oncellclick
 * @description grd_inqDiscls 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_inqDiscls_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_inqDiscls');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_inqDiscls */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: updateInqDiscls (조건 미해석) */
        if (r["procsCompltYn"] !== 'Y') { await scwin.goWrite(r["reqFormCd"], r["reqFormVer"], r["acptNo"]); return; }
        scwin.goViewer(r["acptNoAns"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_inqDiscls.oncellclick' });
    }
};

/**
 * @method
 * @name grd_explDiscls_oncellclick
 * @description grd_explDiscls 셀 클릭 이벤트
