 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_explDiscls_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_explDiscls');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_explDiscls */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: updateExplDiscls (조건 미해석) */
        if (columnId === "__rowAct") { scwin.goViewer(r["acptNo"]); return; } scwin.updateExplDiscls(r["orgAcptNo"], r["count"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_explDiscls.oncellclick' });
    }
};

