///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_updateInqDiscls
 * @description update Inq Discls 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_updateInqDiscls = async function () {
    const sbmOptions = {
        id: "tx_updateInqDiscls",
        method: "post",
        action: "/combasinfo/comOvrvw.do?method=updateInqDiscls",
        ref: "dma_updateInqDisclsReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_updateExplDiscls
 * @description update Expl Discls 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
