/**
 * @method
 * @name numberFormat
 * @description number Format 처리
 * @param {*} numstr numstr
 * @param {*} ret ret
 * @returns {void}
 * @hidden N
 */
scwin.numberFormat = function (numstr, ret) {
    if (numstr != null && numstr !== '') {
        numstr = scwin.setComma(scwin.delComma(numstr));
        if (ret) {
            ret.value = numstr;
        }
        return numstr;
    }
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @param {*} numstr numstr
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function (numstr) {
    numstr = String(numstr);
    const re0 = /^(-?\d+)(\d{3})($|\..*$)/;
    if (re0.test(numstr)) {
        return numstr.replace(re0, function(str, p1, p2, p3) {
                return scwin.setComma(p1) + ',' + p2 + p3;
        });
    } else {
        return numstr;
    }
};

/**
 * @method
 * @name delComma
 * @description del Comma 처리
 * @param {*} numstr numstr
 * @returns {void}
 * @hidden N
 */
scwin.delComma = function (numstr) {
    numstr = String(numstr);
    if (numstr === '') {
        return '';
    } else {
        if (numstr === '0-') {
            return '';
        }
    }
    numstr = numstr.replace(/[^\d\.-]/g, '');
    numstr = String(numstr.match(/^-?\d*\.?\d*/));
    numstr = numstr.replace(/^(-?)(\d*)(.*)/, function(str, p1, p2, p3) {
            p2 = (p2 > 0) ? String(p2.match(/[1-9]\d*$/)) : '0';
            return p1 + p2 + p3;
    });
    return numstr;
};

/**
 * @method
 * @name updateInqDiscls
 * @description update Inq Discls 처리
 * @param {*} acpt_no acpt_no
 * @param {*} seqNum seqNum
 * @returns {void}
 * @hidden N
 */
scwin.updateInqDiscls = function (acpt_no, seqNum) {
    $c.util.getComponent('ipt_SCREN_PROCES_TP_CD').setValue("03");
    $c.util.getComponent('ipt_acptNo').setValue(acpt_no);
    $c.util.getComponent('ipt_procsCompltYn').setValue($('#inqDisclsProcs_complt_yn' + seqNum).val());
    scwin.confirmE("저장하시겠습니까?", "updateInqDiscls");
};

