 * @name confirmE
 * @description confirm E 처리
 * @param {String} msg 항목명
 * @param {*} ipt_method ipt_method
 * @returns {void}
 * @hidden N
 */
scwin.confirmE = function (msg, ipt_method) {
    $c.util.getComponent('ipt_method').setValue(ipt_method);
    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pConfirmText')[0].innerText = msg;
    scwin.divConfirmMsg.setStyle("display", "");
};

/**
 * @method
 * @name goSubmit
 * @description go Submit 처리
 * @returns {void}
 * @hidden N
 */
scwin.goSubmit = function () {
    ipt_method = $c.util.getComponent('ipt_method').getValue();
    const action = "/combasinfo/comOvrvw.do?method=" + ipt_method;
    $('#miscStatForm').attr("action", action);
    $('#miscStatForm').submit();
};

/**
