/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {*} ipt_acptNo ipt_acptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (formCd, formVer, ipt_acptNo) {
    const url = '/jldfil00000/jldfil00000.xml';
    await $c.win.openPopup(url, { id: "reportPop", scrollbars: true, resizable: false, width: "635", height: "495", type: "pageFramePopup" }, { method: "searchReportPop", formCd: formCd, formVer: formVer, inqOrgnDisclsAcptNo: ipt_acptNo });
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }
